  "const pipe = <T>(...fns: Array<(arg: T) => T>) => (value: T) => fns.reduce((acc, fn) => fn(acc), value);\nconst add5 = (x: number) => x + 5;\nconst multiply2 = (x: number) => x * 2;\nconst result = pipe(add5, multiply2)(10);",
