  "interface Store<S, A> {\n  getState(): S;\n  dispatch(action: A): void;\n  subscribe(listener: () => void): () => void;\n}\nconst createStore = <S, A>(reducer: (state: S, action: A) => S, initialState: S): Store<S, A> => { /* implementation */ };",
